1	import { Router } from "express";
2	import { eq } from "drizzle-orm";
3	import type { Db } from "@paperclipai/db";
4	import { authUsers } from "@paperclipai/db";
5	import {
6	  authSessionSchema,
7	  currentUserProfileSchema,
8	  updateCurrentUserProfileSchema,
9	} from "@paperclipai/shared";
10	import { unauthorized } from "../errors.js";
11	import { validate } from "../middleware/validate.js";
12	
13	async function loadCurrentUserProfile(db: Db, userId: string) {
14	  const user = await db
15	    .select({
16	      id: authUsers.id,
17	      email: authUsers.email,
18	      name: authUsers.name,
19	      image: authUsers.image,
20	    })
21	    .from(authUsers)
22	    .where(eq(authUsers.id, userId))
23	    .then((rows) => rows[0] ?? null);
24	
25	  if (!user) {
26	    throw unauthorized("Signed-in user not found");
27	  }
28	
29	  return currentUserProfileSchema.parse({
30	    id: user.id,
31	    email: user.email ?? null,
32	    name: user.name ?? null,
33	    image: user.image ?? null,
34	  });
35	}
36	
37	export function authRoutes(db: Db) {
38	  const router = Router();
39	
40	  router.get("/get-session", async (req, res) => {
41	    if (req.actor.type !== "board" || !req.actor.userId) {
42	      throw unauthorized("Board authentication required");
43	    }
44	
45	    const user = await loadCurrentUserProfile(db, req.actor.userId);
46	    res.json(authSessionSchema.parse({
47	      session: {
48	        id: `paperclip:${req.actor.source ?? "none"}:${req.actor.userId}`,
49	        userId: req.actor.userId,
50	      },
51	      user,
52	    }));
53	  });
54	
55	  router.get("/profile", async (req, res) => {
56	    if (req.actor.type !== "board" || !req.actor.userId) {
57	      throw unauthorized("Board authentication required");
58	    }
59	
60	    res.json(await loadCurrentUserProfile(db, req.actor.userId));
61	  });
62	
63	  router.patch("/profile", validate(updateCurrentUserProfileSchema), async (req, res) => {
64	    if (req.actor.type !== "board" || !req.actor.userId) {
65	      throw unauthorized("Board authentication required");
66	    }
67	
68	    const patch = updateCurrentUserProfileSchema.parse(req.body);
69	    const now = new Date();
70	
71	    const updated = await db
72	      .update(authUsers)
73	      .set({
74	        name: patch.name,
75	        ...(patch.image !== undefined ? { image: patch.image } : {}),
76	        updatedAt: now,
77	      })
78	      .where(eq(authUsers.id, req.actor.userId))
79	      .returning({
80	        id: authUsers.id,
81	        email: authUsers.email,
82	        name: authUsers.name,
83	        image: authUsers.image,
84	      })
85	      .then((rows) => rows[0] ?? null);
86	
87	    if (!updated) {
88	      throw unauthorized("Signed-in user not found");
89	    }
90	
91	    res.json(currentUserProfileSchema.parse({
92	      id: updated.id,
93	      email: updated.email ?? null,
94	      name: updated.name ?? null,
95	      image: updated.image ?? null,
96	    }));
97	  });
98	
99	  return router;
100	}
